query IssueQuery($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    issueOrPullRequest(number: $number) {
      __typename
      ... on Issue {
        id
        number
        title
        body
        state
        stateReason
        author {
          login
        }
        createdAt
        labels(first: 20) {
          totalCount
          nodes {
            name
            color
          }
        }
        assignees(first: 10) {
          totalCount
          nodes {
            login
          }
        }
        milestone {
          number
          title
        }
        comments(last: 100) {
          totalCount
          nodes {
            id
            fullDatabaseId
            author {
              login
            }
            body
            createdAt
            viewerCanUpdate
            viewerCanDelete
            viewerCanReact
            reactionGroups {
              content
              viewerHasReacted
              reactors {
                totalCount
              }
            }
          }
        }
        repository {
          nameWithOwner
        }
        viewerCanClose
        viewerCanReopen
        viewerCanUpdate
        viewerCanReact
        viewerCanLabel
        viewerCanAssign
        viewerCanSetMilestone
        reactionGroups {
          content
          viewerHasReacted
          reactors {
            totalCount
          }
        }
      }
      ... on PullRequest {
        number
      }
    }
  }
}
